import type { Models } from "@earendil-works/pi-ai/models";
import type { Extension } from "@earendil-works/pi-durable";

import { Activity, formatStats, oneLine } from "./activity.ts";
import {
	buildPrompt,
	formatFollowUp,
	type PIContext,
	withReplyReminder,
} from "./context.ts";
import { ThreadConversation, type ThreadResult } from "./conversation.ts";
import { createDurableExtensions } from "./durable-extensions.ts";
import { loadExtensions } from "./extensions.ts";
import {
	formatErrorComment,
	formatSuccessComment,
	formatThreadLog,
	formatThreadSummary,
} from "./formatting.ts";
import { createGitHubUi, type GitHubUi } from "./github-ui.ts";
import {
	type GitHubClient,
	isForkPullRequest,
	type ReactionTarget,
} from "./github.ts";
import type { ActionInputs } from "./inputs.ts";
import { createActionModels, findModel } from "./models.ts";
import { getRunContext } from "./run-context.ts";
import { GitSyncConflictError } from "./storage/sync.ts";
import type { SnapshotLimits } from "./storage/worktree.ts";
import { Thread } from "./thread.ts";
import { toolEnv } from "./tool-env.ts";
import { collectTriggers, type Trigger, triggerFromInfo } from "./triggers.ts";
import type { Log, TriggerInfo } from "./types.ts";
import { getErrorMessage } from "./utils.ts";

type Env = Record<string, string | undefined>;

export interface Logger extends Log {
	debug: (msg: string) => void;
	error: (msg: string) => void;
	setFailed: (msg: string) => void;
	setOutput: (name: string, value: string) => void;
	startGroup: (name: string) => void;
	endGroup: () => void;
}

export interface ActionDependencies {
	inputs: ActionInputs;
	/** The webhook payload of the event that started the workflow. */
	payload: Record<string, unknown>;
	createClient: (token: string) => GitHubClient;
	log: Logger;
	cwd: string;
	/** Override model setup (tests use a faux provider). */
	createModels?: ((inputs: ActionInputs) => Promise<Models>) | undefined;
	/** Git remote holding the thread refs. Default "origin". */
	remote?: string;
	env?: Env;
	/** Appends Markdown to the job summary (notifications from pi-durable extensions). */
	summary?: (markdown: string) => Promise<void>;
}

/**
 * The `extensions` input and the model setup: the built-in and custom providers and those extensions register
 * (unless `createModels` overrides it), the pi-durable extensions for the thread, which get the GitHub UI when
 * the run posts to an issue or PR, and the variables the agent's tools get (see `toolEnv()`). pi-durable extensions
 * run in this process, so when there are any, those variables are set in its environment too (after npm ran).
 */
async function setUp(
	deps: ActionDependencies,
	gh: GitHubClient,
	issueNumber: number | undefined,
): Promise<{
	models: Models;
	extensions: Extension[];
	tools: Record<string, string>;
	ui: GitHubUi | undefined;
}> {
	const { inputs, log, cwd } = deps;
	const env = deps.env ?? process.env;
	const loaded = await loadExtensions({
		specs: inputs.extensions,
		cwd,
		log,
		env,
	});
	const models = deps.createModels
		? await deps.createModels(inputs)
		: await createActionModels(inputs, {
				providers: loaded.providers,
				env,
				log,
			});
	const tools = await toolEnv({ token: inputs.githubToken, cwd, env });
	if (Object.keys(tools).length > 0) {
		log.info(`The agent's tools get ${Object.keys(tools).join(", ")}`);
	}
	if (loaded.durable.length > 0) {
		Object.assign(env, tools);
	}
	const ui =
		inputs.outputMode === "comment" && issueNumber !== undefined
			? createGitHubUi({ gh, issueNumber, log, summary: deps.summary })
			: undefined;
	const extensions = await createDurableExtensions(loaded.durable, {
		cwd,
		agentDir: inputs.agentDir,
		trustProject: inputs.trustProject,
		ui,
		log,
		env,
	});
	return { models, extensions, tools, ui };
}

/** On cancellation (SIGINT, then SIGTERM), push what the thread has so far before the runner kills us. */
function pushOnSignals(thread: Thread, log: Log): () => void {
	const handler = (signal: NodeJS.Signals) => {
		log.warning(`Received ${signal}; saving the thread before exiting`);
		thread
			.push()
			.catch((error: unknown) => {
				log.warning(getErrorMessage(error));
			})
			.finally(() => {
				process.exitCode = 1;
				process.kill(process.pid, "SIGKILL");
			})
			.catch(() => undefined);
	};
	process.once("SIGINT", handler);
	process.once("SIGTERM", handler);
	return () => {
		process.off("SIGINT", handler);
		process.off("SIGTERM", handler);
	};
}

/** One line for the model and the pi-durable extensions, after the setup group. */
function describeSetup(
	inputs: ActionInputs,
	extensions: readonly Extension[],
): string {
	const loaded = extensions.map(
		(extension) =>
			`${extension.name} (${(extension.tools ?? []).map((tool) => tool.name).join(", ") || "no tools"})`,
	);
	return `🤖 ${inputs.provider}/${inputs.model}${loaded.length > 0 ? ` · extensions: ${loaded.join(", ")}` : ""}`;
}

/** One line for a request as pi gets it: who, where, and its first line. */
function describeTrigger(trigger: Trigger): string {
	const what = trigger.answer ? "Answer" : "Request";
	const where = trigger.url ? ` (${trigger.url})` : "";
	return `▶ ${what} from @${trigger.author.login}${where}: ${oneLine(trigger.task || trigger.text)}`;
}

/** The context of the first message of a thread, for the trigger that starts it. */
function contextFor(piContext: PIContext, trigger: Trigger): PIContext {
	return piContext.type === "direct"
		? piContext
		: { ...piContext, task: trigger.task, triggerComment: trigger.text };
}

/** A run from workflow_dispatch or a direct prompt: one request, keyed by the workflow run. */
function oneOffTrigger(piContext: PIContext, env: Env): Trigger {
	const runId = env["GITHUB_RUN_ID"] ?? String(Date.now());
	const attempt = env["GITHUB_RUN_ATTEMPT"] ?? "1";
	return {
		key: `run-${runId}-${attempt}`,
		source: "body",
		issueNumber: piContext.type === "direct" ? 0 : piContext.number,
		author: { login: env["GITHUB_ACTOR"] ?? "workflow", type: "User" },
		text: piContext.task,
		task: piContext.task,
		createdAt: new Date().toISOString(),
	};
}

/** What the run starts with: every unanswered trigger on the thread in comment mode, else one request. */
async function initialTriggers(
	deps: ActionDependencies,
	gh: GitHubClient,
	piContext: PIContext,
	triggerInfo: TriggerInfo | undefined,
	since: Date | undefined,
	answer: Trigger | undefined,
): Promise<Trigger[]> {
	const { inputs } = deps;
	if (!triggerInfo) {
		return [oneOffTrigger(piContext, deps.env ?? process.env)];
	}
	const current = answer ?? triggerFromInfo(triggerInfo, inputs.triggerPhrase);
	return inputs.outputMode === "comment"
		? collectTriggers(gh, triggerInfo, inputs, since, current)
		: [current];
}

/** The working-tree snapshot limits of the thread; undefined (off) by input and on fork pull requests. */
function worktreeLimits(deps: ActionDependencies): SnapshotLimits | undefined {
	const { inputs, log } = deps;
	if (!inputs.worktreeSnapshots) {
		return undefined;
	}
	if (isForkPullRequest(deps.payload)) {
		log.info(
			"A pull request from a fork: its token can't push, so the working tree is not saved",
		);
		return undefined;
	}
	return inputs.worktreeLimits;
}

/** Close the thread, pushing it; a failure to save is a warning, not a failed run. */
async function closeThread(thread: Thread, log: Log): Promise<void> {
	try {
		await thread.close();
	} catch (error) {
		log.warning(
			error instanceof GitSyncConflictError
				? `${thread.ref} moved on the remote while this run worked; its history was not pushed. ${getErrorMessage(error)}`
				: `Could not save the thread: ${getErrorMessage(error)}`,
		);
	}
}

/** The thread, first thing in the log: whether it is new, with how to read it with git in its group. */
function announceThread(deps: ActionDependencies, thread: Thread): void {
	const { log } = deps;
	if (thread.ref === undefined) {
		log.info("🧵 One-off conversation (not stored)");
		return;
	}
	const since = thread.startedAt
		?.toISOString()
		.replace(/:\d\d\.\d+Z$/u, " UTC");
	log.startGroup(
		`🧵 Thread ${thread.ref}: ${since === undefined ? "new" : `continuing, started ${since.replace("T", " ")}`}`,
	);
	log.info(formatThreadLog(thread.ref, deps.remote ?? "origin"));
	log.endGroup();
}

/** After the final push: where the thread is now, in the log, and how to read it, in the job summary. */
async function showThread(
	deps: ActionDependencies,
	thread: Thread,
	ref: string,
): Promise<void> {
	const { log } = deps;
	const remote = deps.remote ?? "origin";
	const { tip } = thread;
	log.info(
		`🧵 ${ref} is at ${tip === undefined ? "(nothing stored)" : tip.slice(0, 7)}`,
	);
	try {
		await deps.summary?.(formatThreadSummary(ref, remote));
	} catch (error) {
		log.warning(`Could not write the job summary: ${getErrorMessage(error)}`);
	}
}

export async function run(deps: ActionDependencies): Promise<void> {
	const resolved = await getRunContext(deps);
	if (!resolved) {
		return;
	}
	const { piContext, ghClient: gh, triggerInfo } = resolved;
	const { inputs, log } = deps;
	const activity = new Activity(log);
	const issueNumber =
		piContext.type === "direct" ? undefined : piContext.number;
	// In comment mode, a trigger makes the run a conversation on its issue or PR (reactions, new comments join).
	const interactive = inputs.outputMode === "comment" ? triggerInfo : undefined;

	/** Set the outputs, or react on `target` and post the result unless it was posted before. Returns where it went. */
	const report = async (
		result: ThreadResult,
		target: ReactionTarget | undefined,
		ref?: string,
		alreadyPosted = false,
	): Promise<string | undefined> => {
		if (!result.success) {
			log.error(`pi execution failed: ${result.error}`);
		}
		const stats = formatStats(activity.take());
		if (inputs.outputMode === "output") {
			log.info(`${result.success ? "✅" : "❌"} Set the outputs (${stats})`);
			log.setOutput("success", String(result.success));
			log.setOutput(
				"response",
				result.success ? result.response : result.error,
			);
			return "output";
		}
		if (target) {
			await gh.addReaction(target, result.success ? "rocket" : "confused");
		}
		if (alreadyPosted || issueNumber === undefined) {
			return undefined;
		}
		const body = result.success
			? formatSuccessComment(result.response, ref)
			: formatErrorComment(result.error, ref);
		const { url } = await gh.createComment(issueNumber, body);
		log.info(
			`${result.success ? "✅ Replied" : "❌ Reported the error"}: ${url} (${stats})`,
		);
		return url;
	};

	if (interactive) {
		await gh.addReaction(interactive, "eyes");
	}
	let thread: Thread | undefined;
	let stopSignals: (() => void) | undefined;
	try {
		log.startGroup("Setup");
		let setup: Awaited<ReturnType<typeof setUp>>;
		try {
			setup = await setUp(deps, gh, issueNumber);
		} finally {
			log.endGroup();
		}
		const { models, extensions, tools, ui } = setup;
		log.info(describeSetup(inputs, extensions));
		const opened = await Thread.open({
			cwd: deps.cwd,
			issueNumber,
			models,
			model: findModel(models, inputs.provider, inputs.model),
			log,
			remote: deps.remote,
			extensions,
			toolEnv: tools,
			worktree: worktreeLimits(deps),
			onEntries: (entries) => {
				activity.entries(entries);
			},
		});
		thread = opened;
		stopSignals = pushOnSignals(opened, log);
		announceThread(deps, opened);
		// New comments: on a new thread, from the time of the trigger; on an existing one, since it began.
		const since =
			opened.startedAt ??
			new Date(
				Date.parse(interactive?.createdAt ?? new Date().toISOString()) - 1000,
			);
		const conversation = new ThreadConversation({
			thread: opened,
			log,
			timeoutSeconds: inputs.timeout,
			pollIntervalMs: inputs.pollInterval * 1000,
			message: async (trigger, first) => {
				// As `report` does, pi-action posts the reply: say so, or pi may post it with `gh` too (#42).
				const repliesAsComment =
					inputs.outputMode === "comment" && issueNumber !== undefined;
				if (first && !trigger.answer) {
					return buildPrompt(
						contextFor(piContext, trigger),
						inputs.promptTemplate,
						{ repliesAsComment },
					);
				}
				const message = trigger.answer ? trigger.text : formatFollowUp(trigger);
				return repliesAsComment ? withReplyReminder(message) : message;
			},
			started: (trigger) => {
				log.info(describeTrigger(trigger));
			},
			deliver: async (trigger, result, alreadyPosted) =>
				report(
					result,
					interactive ? trigger : undefined,
					opened.ref,
					alreadyPosted,
				),
			...(interactive
				? { poll: async () => collectTriggers(gh, interactive, inputs, since) }
				: {}),
			...(ui ? { asked: () => ui.asked } : {}),
		});
		await conversation.run(
			await initialTriggers(
				deps,
				gh,
				piContext,
				triggerInfo,
				opened.startedAt,
				resolved.answer,
			),
		);
		if (conversation.failures.length > 0) {
			log.setFailed(
				`pi could not answer ${conversation.failures.length} comment(s): ${conversation.failures.join("; ")}`,
			);
		}
	} catch (error) {
		await report(
			{ success: false, error: getErrorMessage(error) },
			interactive,
		);
	} finally {
		stopSignals?.();
		if (thread) {
			await closeThread(thread, log);
			if (thread.ref !== undefined) {
				await showThread(deps, thread, thread.ref);
			}
		}
	}
}
import { setTimeout as sleep } from "node:timers/promises";

import { BACKGROUND_CONTEXT } from "@earendil-works/chord/context";
import type { Submission } from "@earendil-works/pi-durable";

import { ANSWER_KIND } from "./answers.ts";
import type { Thread } from "./thread.ts";
import type { Trigger } from "./triggers.ts";
import type { Log } from "./types.ts";
import { getErrorMessage } from "./utils.ts";

type SettledRecord = Awaited<ReturnType<Submission["wait"]>>;

export type ThreadResult =
	| { success: true; response: string }
	| { success: false; error: string };

export interface ConversationOptions {
	thread: Thread;
	log: Log;
	timeoutSeconds: number;
	pollIntervalMs: number;
	/** The message to submit for a trigger; `first` is true for the first one of a new thread. */
	message: (trigger: Trigger, first: boolean) => Promise<string>;
	/**
	 * Deliver a result. `alreadyPosted` is set when an earlier run delivered this answer (the trigger was
	 * answered together with another one). Returns where it was posted, recorded so it is never posted twice.
	 */
	deliver: (
		trigger: Trigger,
		result: ThreadResult,
		alreadyPosted: boolean,
	) => Promise<string | undefined>;
	/** Triggers that arrived since the run started; omitted for one-off runs. */
	poll?: () => Promise<Trigger[]>;
	/**
	 * Called when pi starts on a trigger: once it is submitted, unless an earlier run already settled it (a run
	 * resubmits every trigger on the thread, and only the unsettled ones are news).
	 */
	started?: (trigger: Trigger) => void;
	/** The URLs of the questions pi-durable extensions asked in this run so far (see github-ui.ts). */
	asked?: () => readonly string[];
}

const EMPTY_RESPONSE = "Agent returned empty response";
const SUMMARY_SUFFIX = "-summary";
const CONTINUE_SUFFIX = "-continue-";
/**
 * Sent once when a run ends on a normal stop with no text. Neutral on purpose: the model may have stopped
 * early, so it is not told its work is done, and tools stay available to finish (it must still end with text).
 */
const SUMMARY_PROMPT = `Your last turn ended without a text reply, and a reply is required: it is posted to the issue or pull request. Write a plain-text reply that covers:
- What you did, and which files you changed (if any)
- What is left to do, if anything
- Any errors or open problems

If something you were asked to do is still unfinished and you can finish it, you may continue with tools first. Either way, end your turn with that text reply.`;
/** Sent when a response ran out of output tokens with no tool call: the model did not choose to stop. */
const CONTINUE_PROMPT =
	"Your last response hit the output token limit (max_tokens) before you finished. Continue where you left off; keep reasoning shorter and act with tools.";
/** How many responses in a row may hit the output token limit before the run gives up. */
const MAX_CUT_OFFS = 3;
const CUT_OFF_NOTE =
	"\n\n_This response was cut off at the output token limit (max_tokens); pi is continuing._";

/** A response that hit the output token limit too often (or at the timeout): an error with any partial text. */
function cutOffResult(
	text: string,
	count: number,
	timedOutAfter: number | undefined,
): ThreadResult {
	const reason =
		timedOutAfter === undefined
			? `pi's responses hit the output token limit (max_tokens) ${count} times in a row, so the run stopped before the work was finished. Raise \`model_max_tokens\` (for a custom provider) or use a model with a larger output limit, then ask again.`
			: `Timeout after ${timedOutAfter} seconds, while the last response was cut off at the output token limit (max_tokens).`;
	return {
		success: false,
		error: text
			? `${reason}\n\nThe last response, cut off:\n\n${text}`
			: reason,
	};
}

function describeUnanswered(
	record: SettledRecord,
	timedOutAfter: number | undefined,
): string {
	if (record.reason === "aborted" && timedOutAfter !== undefined) {
		return `Timeout after ${timedOutAfter} seconds`;
	}
	if (record.detail === undefined) {
		return record.reason ?? "unanswered";
	}
	const detail =
		typeof record.detail === "string"
			? record.detail
			: JSON.stringify(record.detail);
	return `${record.reason}: ${detail}`;
}

/** How many causes `withCause()` follows. */
const MAX_CAUSES = 5;

/**
 * An error's message with the messages of its causes: pi-durable's SessionFailed carries the storage error as its
 * cause, which may have its own cause (a ref that moved, say).
 */
function withCause(error: unknown): string {
	const messages = [getErrorMessage(error)];
	let cause: unknown = error instanceof Error ? error.cause : undefined;
	while (cause !== undefined && messages.length <= MAX_CAUSES) {
		messages.push(getErrorMessage(cause));
		cause = cause instanceof Error ? cause.cause : undefined;
	}
	return messages.join(": ");
}

/**
 * Drives a thread through a set of triggers: submits them (new ones join the running conversation), waits for
 * every answer within the timeout, and delivers each answer or failure exactly once.
 */
export class ThreadConversation {
	private readonly handled = new Set<string>();
	private readonly pending = new Set<Promise<void>>();
	private delivering: Promise<void> = Promise.resolve();
	private posted = new Map<string, string>();
	private timedOut = false;
	/** When the run times out; set once the initial triggers are submitted. */
	private deadline = Number.POSITIVE_INFINITY;
	private readonly options: ConversationOptions;
	/** Why triggers could not be answered at all (the session failed, say): each was reported as an error. */
	private readonly unanswered: string[] = [];

	constructor(options: ConversationOptions) {
		this.options = options;
	}

	async run(initial: Trigger[]): Promise<void> {
		const { thread, log, timeoutSeconds, pollIntervalMs, poll } = this.options;
		this.posted = await thread.postedResults();
		await this.submitAll(initial);

		this.deadline = Date.now() + timeoutSeconds * 1000;
		for (;;) {
			const remaining = this.deadline - Date.now();
			if (remaining <= 0) {
				this.timedOut = true;
				break;
			}
			if (this.pending.size > 0) {
				const wait = new AbortController();
				const timer = sleep(Math.min(pollIntervalMs, remaining), undefined, {
					signal: wait.signal,
				}).catch(() => undefined);
				// oxlint-disable-next-line eslint/no-await-in-loop -- the poll loop waits between rounds by design
				await Promise.race([Promise.allSettled(this.pending), timer]);
				wait.abort();
			}
			const fresh = poll
				? // oxlint-disable-next-line eslint/no-await-in-loop -- each round polls once, after the wait
					(await poll()).filter((trigger) => !this.handled.has(trigger.key))
				: [];
			if (fresh.length > 0) {
				log.info(
					`${fresh.length} new comment(s) for pi; adding them to the conversation`,
				);
				// oxlint-disable-next-line eslint/no-await-in-loop -- new comments join before the next round
				await this.submitAll(fresh);
			} else if (this.pending.size === 0) {
				break;
			}
		}

		if (this.timedOut) {
			log.warning(`Timeout after ${timeoutSeconds} seconds; aborting the run`);
			await thread.abort();
		}
		await Promise.allSettled(this.pending);
		await this.delivering;
	}

	private async submitAll(triggers: Trigger[]): Promise<void> {
		for (const trigger of triggers) {
			if (!this.handled.has(trigger.key)) {
				const first = this.options.thread.isNew && this.handled.size === 0;
				this.handled.add(trigger.key);
				// oxlint-disable-next-line eslint/no-await-in-loop -- triggers are submitted in order
				const content = await this.options.message(trigger, first);
				this.track(trigger, this.answer(trigger, content));
			}
		}
	}

	/** The errors of triggers that got no answer, not even a failed one; empty when every trigger was answered. */
	get failures(): readonly string[] {
		return this.unanswered;
	}

	private track(trigger: Trigger, result: Promise<SettledResult>): void {
		const settled = (async () => {
			let outcome: SettledResult;
			try {
				outcome = await result;
			} catch (error) {
				// Waiting for the answer threw (the session failed after a storage error, say): report it on the
				// trigger, or it gets no reply and no reaction at all (#46).
				const message = withCause(error);
				this.options.log.warning(message);
				this.unanswered.push(message);
				outcome = {
					key: `failed-${trigger.key}`,
					empty: false,
					result: { success: false, error: message },
				};
			}
			this.enqueueDelivery(trigger, outcome);
		})();
		this.pending.add(settled);
		settled
			.finally(() => {
				this.pending.delete(settled);
			})
			.catch(() => undefined);
	}

	/**
	 * Submit and wait. A response cut off by the output token limit is continued (see `settle()`); an empty
	 * answer is followed by one request for a summary (as pi-action always did).
	 */
	private async answer(
		trigger: Trigger,
		content: string,
	): Promise<SettledResult> {
		const outcome = await this.settle(trigger, trigger.key, content);
		// An answer an earlier run delivered (or a question it is waiting on) is not asked for again.
		if (!(outcome.empty && !this.outOfTime()) || this.posted.has(outcome.key)) {
			return outcome;
		}
		this.options.log.warning(
			"Agent returned empty response from first attempt. Re-prompting for a summary.",
		);
		const retry = await this.settle(
			trigger,
			`${trigger.key}${SUMMARY_SUFFIX}`,
			SUMMARY_PROMPT,
		);
		if (!retry.empty) {
			return retry;
		}
		return {
			key: retry.key,
			empty: true,
			result: {
				success: false,
				error: `Agent failed to provide a response after two attempts. First attempt: ${EMPTY_RESPONSE}. Retry attempt: ${EMPTY_RESPONSE}.`,
			},
		};
	}

	/**
	 * Submit and wait; while the answer was cut off by the output token limit (no tool call: the agent loop
	 * ended, but the model did not choose to stop), ask it to continue, with tools. Partial text is posted as it
	 * comes. After `MAX_CUT_OFFS` cut-offs in a row (a run that used tools in between resets the count), or at
	 * the timeout, the result is an error that says so. Continuations have stable keys, so a re-run gets the same
	 * submissions back rather than sending them again.
	 */
	private async settle(
		trigger: Trigger,
		key: string,
		content: string,
	): Promise<SettledResult> {
		const { log } = this.options;
		let outcome = await this.submitAndWait(trigger, key, content);
		let inARow = 0;
		for (let continuation = 1; outcome.cutOff; continuation += 1) {
			inARow = outcome.cutOff.usedTools ? 1 : inARow + 1;
			const { text } = outcome.cutOff;
			if (inARow > MAX_CUT_OFFS || this.outOfTime()) {
				const timedOutAfter =
					inARow > MAX_CUT_OFFS ? undefined : this.options.timeoutSeconds;
				log.warning(
					timedOutAfter === undefined
						? `pi's responses hit the output token limit (max_tokens) ${inARow} times in a row; giving up. Consider raising the model_max_tokens input.`
						: "Timed out while pi's response was cut off at the output token limit (max_tokens); not continuing.",
				);
				return {
					key: outcome.key,
					empty: false,
					result: cutOffResult(text, inARow, timedOutAfter),
				};
			}
			log.warning(
				`pi's response hit the output token limit (max_tokens) without a tool call; asking it to continue (${inARow} of ${MAX_CUT_OFFS}). Consider raising the model_max_tokens input.`,
			);
			if (text) {
				this.enqueueDelivery(trigger, {
					key: outcome.key,
					empty: false,
					result: { success: true, response: `${text}${CUT_OFF_NOTE}` },
				});
			}
			// oxlint-disable-next-line eslint/no-await-in-loop -- each continuation follows the cut-off one
			outcome = await this.submitAndWait(
				trigger,
				`${key}${CONTINUE_SUFFIX}${continuation}`,
				CONTINUE_PROMPT,
			);
		}
		return outcome;
	}

	/** The run timed out, or is about to: no more prompts are sent. */
	private outOfTime(): boolean {
		return this.timedOut || Date.now() >= this.deadline;
	}

	private async submitAndWait(
		trigger: Trigger,
		key: string,
		content: string,
	): Promise<SettledResult> {
		const asked = this.options.asked ?? (() => []);
		const askedBefore = asked().length;
		const { answer } = trigger;
		const submission = await this.options.thread.submit({
			key,
			content,
			data: {
				author: trigger.author.login,
				source: trigger.source,
				...(trigger.url ? { url: trigger.url } : {}),
			},
			...(answer
				? {
						entry: {
							kind: ANSWER_KIND,
							data: {
								key: answer.key,
								kind: answer.kind,
								answer: answer.answer,
								by: answer.by,
								url: answer.url,
							},
						},
					}
				: {}),
		});
		if (key === trigger.key && this.options.started !== undefined) {
			const { status } = await submission.status(BACKGROUND_CONTEXT);
			if (status !== "done" && status !== "unanswered") {
				this.options.started(trigger);
			}
		}
		const record = await submission.wait(BACKGROUND_CONTEXT);
		if (record.status === "done" && record.answer !== undefined) {
			// An input submission always has its entry; without one, the range is just the answer.
			const input = record.entry ?? record.answer;
			const { text, toolCalls, stopReason, usedTools } =
				await this.options.thread.answerText(record.answer, input);
			const questions = asked().slice(askedBefore);
			if (toolCalls && questions.length > 0) {
				// The run ended on a question (its tool round asked to terminate): the answer comes in a later run.
				return {
					key: `answer-${record.answer}`,
					empty: false,
					waiting: questions,
					result: { success: true, response: text },
				};
			}
			if (stopReason === "length" && !toolCalls) {
				return {
					key: `answer-${record.answer}`,
					empty: false,
					cutOff: { text, usedTools },
					result: { success: true, response: text },
				};
			}
			return {
				key: `answer-${record.answer}`,
				empty: text === "",
				result: text
					? { success: true, response: text }
					: { success: false, error: EMPTY_RESPONSE },
			};
		}
		const timedOutAfter = this.timedOut
			? this.options.timeoutSeconds
			: undefined;
		return {
			key: `error-${record.id}`,
			empty: false,
			result: {
				success: false,
				error: describeUnanswered(record, timedOutAfter),
			},
		};
	}

	private enqueueDelivery(trigger: Trigger, outcome: SettledResult): void {
		this.delivering = this.delivering
			.then(async () => this.deliver(trigger, outcome))
			.catch((error: unknown) => {
				this.options.log.warning(
					`Failed to deliver result: ${getErrorMessage(error)}`,
				);
			});
	}

	private async deliver(
		trigger: Trigger,
		outcome: SettledResult,
	): Promise<void> {
		const alreadyPosted = this.posted.has(outcome.key);
		if (outcome.waiting) {
			this.options.log.info(
				`pi asked a question and ended its turn; waiting for an answer to ${outcome.waiting.join(", ")}`,
			);
			if (!alreadyPosted) {
				this.posted.set(outcome.key, outcome.waiting[0] ?? "");
				await this.options.thread.markPosted(
					outcome.key,
					outcome.waiting[0] ?? "",
				);
			}
			return;
		}
		if (alreadyPosted && !outcome.result.success) {
			return; // a failure an earlier run already reported
		}
		const url = await this.options.deliver(
			trigger,
			outcome.result,
			alreadyPosted,
		);
		if (url !== undefined && !alreadyPosted) {
			this.posted.set(outcome.key, url);
			await this.options.thread.markPosted(outcome.key, url);
		}
	}
}

interface SettledResult {
	/** `answer-<entryId>`, `error-<submissionId>`, or `failed-<trigger key>`: what is delivered once. */
	key: string;
	empty: boolean;
	result: ThreadResult;
	/** The run ended on these questions: nothing is posted, the answers start a later run. */
	waiting?: readonly string[];
	/** The answer hit the output token limit with no tool call (`settle()` continues it). */
	cutOff?: { text: string; usedTools: boolean };
}
# Extensions

The `extensions` input loads two kinds of packages into pi-action:

- **pi extensions** give model **providers**. pi-action uses only the providers that they register. See [Providers](#providers).
- **pi-durable extensions** give **tools and prompt sections** to every conversation. Their tools can ask questions, which pi-action posts on the issue or pull request. See [pi-durable extensions](#pi-durable-extensions).

An extension is code that runs inside pi-action, with all the permissions of the job. Load only extensions that you trust. See [Security](security.md#extensions).

## Declare extensions

Write one extension per line, or separate them with commas. pi-action ignores empty lines and `#` comments. A comment can be a full line, or it can follow a spec after a space. The `#` in a git ref such as `github:owner/repo#v1.0.0` is not a comment, because no space comes before it:

```yaml
- uses: cv/pi-action@v2
  with:
    github_token: ${{ secrets.GITHUB_TOKEN }}
    extensions: |
      # pi-durable extensions
      github:cv/pit#v0.35.0          # pit's typescript tool
      # pi extensions (providers)
      @acme/pi-provider@1.4.2        # from npm, pinned
      ./.pi/extensions/gateway.ts    # in this repository
```

### Sources

- **npm package spec**: `name`, `name@1.2.3`, `@scope/name@^1`, `npm:name`, or `github:owner/repo#ref`.
- **Path**: a value that starts with `./`, `../`, `/`, or `~/`. pi-action resolves it against the workspace (or the home directory, for `~/`).
- pi-action does not support the `git:` sources of pi. Use the npm form `github:owner/repo#ref`.

### Installation

- pi-action installs npm packages into a new directory in `RUNNER_TEMP`, never into your repository. It runs `npm install --ignore-scripts --legacy-peer-deps --omit=dev`.
- npm does not get the `INPUT_*` variables of the action (`github_token`, `api_key`).
- Lifecycle scripts do not run. Thus, packages that need a build step or native modules do not work.
- pi-action does not install the pi packages of an extension (its `peerDependencies`). Imports of `@earendil-works/pi-ai`, `@earendil-works/pi-durable`, and `@earendil-works/chord` (and their subpaths) get the copies of pi-action. Thus, the extension and pi-action share one instance of each.
- pi-action loads paths where they are. It does not install them.
- pi-action runs TypeScript without a build step, with [jiti](https://github.com/unjs/jiti), as pi does.
- If an extension does not load, the run fails.

## Providers

pi-action finds the entry points of a pi extension as pi does:

1. The `pi.extensions` list in `package.json`.
2. If there is no list: the files in the `extensions/` directory (one level deep).
3. If there is no directory: `index.ts` or `index.js`.

From a pi extension, pi-action uses only `pi.registerProvider()`. Both forms work:

- A complete pi-ai `Provider`.
- A name and a config: `baseUrl`, `api`, `apiKey`, `headers`, `authHeader`, `models`, `streamSimple`, and `refreshModels`. If you register a built-in name with only `baseUrl` or `headers`, the built-in provider uses your gateway and keeps its models.

The `apiKey` of a provider config works as in pi: `$ENV_VAR`, `${ENV_VAR}`, `!command`, or a literal key. The `api_key` input has priority when it is set.

pi-action ignores these parts of a pi extension and writes a warning to the log:

- Tools, commands, event handlers, UI, flags, and all other features of the pi coding agent. The agent keeps the read, write, edit, and bash tools of pi-action.
- `oauth` logins, because they cannot run on a runner. Use an API key.
- Image models and classifier models.

To select a provider from an extension, see [Models](models.md#providers-from-pi-extensions).

## pi-durable extensions

A [pi-durable](https://www.npmjs.com/package/@earendil-works/pi-durable) extension adds its tools and prompt sections to every conversation: comment mode, `pr_number` runs, and direct prompts. An example is the `pit/durable` extension of [pit](https://github.com/cv/pit):

```yaml
- uses: cv/pi-action@v2
  with:
    github_token: ${{ secrets.GITHUB_TOKEN }}
    extensions: |
      github:cv/pit#v0.35.0   # pit's typescript tool (pit/durable)
```

### Package format

- A package is a pi-durable extension package when its `package.json` has `pi.durable`, a module path. Example: `"pi": { "durable": "./src/durable/index.ts" }`.
- The module exports `createPiDurableExtension(options)`, or a default export with the same signature.
- The function returns a pi-durable `Extension`: `{ name, tools?, sections?, hooks?, wraps?, tasks? }`.
- If a package has `pi.durable` and `pi.extensions`, pi-action loads only the `pi.durable` entry, because its pi extensions need the pi coding agent. pi-action writes this to the log.
- pi-action installs the extensions after its coding tools (read, write, edit, bash). Each extension must have a unique name.

### Host options

`createPiDurableExtension` receives `{ cwd, agentDir, trustProject, ui, log }`:

| Option | Value |
|--------|-------|
| `cwd` | The workspace |
| `agentDir` | `agent_dir`, resolved against the workspace. If `agent_dir` is empty: a new temporary directory in `RUNNER_TEMP` |
| `trustProject` | The `trust_project` input |
| `ui` | `{ ask, notify }`, the GitHub UI (see [Questions on GitHub](#questions-on-github)). Only in `comment` mode on an issue or pull request. Not set in `output` mode or for direct prompts |
| `log` | The log of the action (`info`, `warning`) |

pi-durable extensions run in the process of pi-action. Thus, pi-action also sets `GH_TOKEN` and the git identity in its own environment when it loads such an extension. See [Security](security.md#the-agents-github-token-and-git-identity).

### `trust_project`

`trust_project` (default `false`) tells the extension that it can load and run the configuration of the repository. For pit, this is `.pi/pit.json` and `.pi/functions`.

Anyone who can push a branch or open a pull request can change those files. Set `trust_project: true` only for repositories whose code you already run. Do not set it in workflows that run on pull requests from people you do not trust.

## Questions on GitHub

A tool can ask its user a question with `ui.confirm`, `ui.select`, or `ui.input`. (pit asks with its `ui.*` globals, and also when it promotes a function to the project.) pi-action posts the question as a comment on the issue or pull request, and **the run ends**. An answer starts a new run, which continues the thread.

pi-action does not wait for the answer, because people can take hours or days to answer.

### The sequence

1. The tool calls `ui.ask` of pi-action. pi-action posts the question and returns its URL immediately. pit stops the program (the calls that it made before the question keep their effects) and ends the turn with "Question posted: ...".
2. The run ends quietly. pi-action posts no `pi Response` comment. The log tells which question pi waits for. pi-action saves the thread as usual.
3. A person answers: they tick a box (an `issue_comment` `edited` event), or they reply `/answer ...` (an `issue_comment` `created` event). The answer starts a new run on the same thread.
4. pi-action checks who answered (see [Security](security.md#answers-to-questions)). It edits the question to show `✅ Answered: <answer> by @user`. It adds the answer to the conversation as a message to pi, together with a `ui.answer` entry. The message is `**@user** answered pi's question *<title>* (<url>): <answer>`.
5. pi runs its step again. When the program asks the same question, pit returns the answer and does not ask again. Each answer is used one time. If the program asks the same question later, pi-action asks again.

The workflow must listen to `issue_comment` `edited` events. Its `if:` filter must let these events and `/answer` replies through. Use the workflow of the [quick start](../README.md#quick-start). pi-action ignores edits of other comments.

### Kinds of questions

| Kind | The comment | How to answer | The value pit gets |
|------|-------------|---------------|--------------------|
| `confirm` | Two boxes: `- [ ] Yes` and `- [ ] No` | Tick one box | `true` for Yes, `false` for No |
| `select` | One box for each option (each option on one line) | Tick one box | The text of the option |
| `input` | A request for a reply | Write a comment that starts with `/answer`, for example `/answer release-2.1` | The text after `/answer` |

- For `confirm` and `select`, the first box that you tick is the answer. pi-action ignores ticks on a question that has an answer.
- An `/answer` reply goes to the `input` question that it quotes (GitHub's *Quote reply*). Without a quote, it goes to the oldest open `input` question. pi-action adds 👍 to the reply.
- pi-action never takes a question or an `/answer` reply as an `@pi` request, also when it contains `@pi`.

### Special cases

- **The same question two times.** While a question is open, pi-action does not post it again. pi waits for the open question.
- **A run that GitHub cancelled.** GitHub keeps only one pending run for each concurrency group. When more events for the issue come while a run works, GitHub can cancel the run for your answer. To answer again, untick and tick the box, or reply `/answer` again.
- **Notifications.** `ui.notify` writes to the log and to the job summary, not to comments.
# Prompts and templates

pi receives three kinds of messages. `prompt_template` changes only the first kind:

| Message | When | Content |
|---------|------|---------|
| **First message** | The first request of a new thread. A direct prompt always has a new thread | The built-in prompt, or your `prompt_template` |
| **Follow-up** | Each later request on the thread: an `@pi` comment, or a `pr_number` run | `**@login** commented (<url>):` and the task. For a review comment: `commented on the diff`. pi-action adds the URL when it has one. Then the [reply reminder](#the-reply) |
| **Answer** | An answer to a question from a pi-durable extension | `**@login** answered pi's question *<title>* (<url>): <answer>` (see [Extensions](extensions.md#questions-on-github)). Then the [reply reminder](#the-reply) |

A follow-up does not repeat the issue or the diff, because the thread already has them. Thus, when a pull request gets new commits, pi does not get a new diff automatically. Ask pi to look at the changes (for example, `@pi review the new commits`): its tools can run `git` and `gh`. See [Durable threads](threads.md).

## The task

The **task** is the text after the first occurrence of the trigger phrase, without spaces at the start and end. The match ignores case. For `@pi please review this`, the task is `please review this`.

Before pi-action finds the task, it removes HTML comments and invisible characters from the text. It does the same to the title and the body of the issue or pull request (see [Security](security.md#what-pi-action-removes-from-text)).

For a `pr_number` run, the task is `prompt`, or `Please review this pull request` when `prompt` is empty. For a direct prompt, the task is `prompt`.

## The built-in prompt

For an issue or a pull request, the built-in first message has these parts, in this sequence:

1. `# GitHub Issue #<number>` or `# GitHub Pull Request #<number>`.
2. `## Title` and `## Description`: the title and body of the issue or pull request.
3. Pull requests only: `## Existing PR Review Comments`, when the pull request has review comments.
4. `## Task`: the task.
5. `output_mode: comment` only: `## Your Reply`, which tells pi not to post its reply itself (see [The reply](#the-reply)).
6. `## Important: Artifact and Script Requirements`: an instruction to commit and push all work, because the runner and its files are deleted after the run.
7. Pull requests only: `## PR Diff`, the diff of the pull request.

For a direct prompt, the message has `# Direct pi Task`, the task, and the requirements block.

## The reply

In `output_mode: comment`, pi-action posts pi's final response as a comment. pi's tools have the token as `GH_TOKEN`, so pi can also post comments with `gh`. If pi posted its reply itself, the issue would get the same answer twice. Thus, pi-action tells pi not to do this:

- The built-in first message has a `## Your Reply` section.
- Each follow-up and each answer ends with this reminder: _(pi-action posts your final response as a comment here. Don't also post it with `gh`.)_ Threads that began before this reminder existed get it too.

In `output_mode: output`, the reply goes to the `response` output, and the messages do not have this text. A [custom template](#custom-templates) replaces the `## Your Reply` section too, but follow-ups and answers still get the reminder.

## Custom templates

`prompt_template` replaces the **complete** built-in first message. pi-action does not add the requirements block to your template. If you want pi to commit and push its work, write this in your template.

pi-action uses the built-in prompt when `prompt_template` is empty or has only spaces.

### Variables

| Variable | Value | Example |
|----------|-------|---------|
| `{{type}}` | `issue`, `pull_request`, or `direct` | `issue` |
| `{{type_display}}` | `Issue`, `Pull Request`, or `Direct Task` | `Pull Request` |
| `{{number}}` | Number of the issue or pull request. `0` for a direct prompt | `42` |
| `{{title}}` | Title of the issue or pull request, without HTML comments and invisible characters. `Direct prompt` for a direct prompt | `Fix login bug` |
| `{{body}}` | Body of the issue or pull request, without HTML comments and invisible characters. Empty for a direct prompt | The full description |
| `{{task}}` | The [task](#the-task) | `please review this code` |
| `{{diff}}` | Diff of the pull request. Empty for issues and direct prompts | A unified diff |
| `{{reviewComments}}` | The `## Existing PR Review Comments` section. Empty when there are none, and for issues | A Markdown section |
| `{{trigger_comment}}` | The full text that contains the trigger phrase, after pi-action removes HTML comments and invisible characters. The task, for `pr_number` runs and direct prompts | `@pi please review this code` |

### Rules

- pi-action replaces `{{name}}` with the value of the variable. Names are case-sensitive.
- pi-action does not change unknown variables. For example, `{{author}}` stays `{{author}}`.
- pi-action inserts values as they are, in one pass. If an issue body contains `{{diff}}`, the text `{{diff}}` stays in the message.
- There are no conditions or loops (for example `{{#if}}`). An empty variable gives empty text. Thus, `{{diff}}` in a template for issues is harmless. To use different templates for issues and pull requests, use different workflows.

## Template examples

### Code review

```yaml
- uses: cv/pi-action@v2
  with:
    github_token: ${{ secrets.GITHUB_TOKEN }}
    prompt_template: |
      # Code review for PR #{{number}}: {{title}}

      ## Description
      {{body}}

      {{reviewComments}}

      ## Request
      {{task}}

      ## Changes
      ```diff
      {{diff}}
      ```

      ## Review guidelines
      - Look for security vulnerabilities.
      - Make sure that tests cover the changes.
      - Make sure that the code follows our style guide.
      - Identify performance problems.
      - Suggest improvements.
```

### Issue triage

```yaml
- uses: cv/pi-action@v2
  with:
    github_token: ${{ secrets.GITHUB_TOKEN }}
    prompt_template: |
      # {{type_display}} triage: {{title}}

      ## Details
      {{body}}

      ## Request
      {{task}}

      ## Triage guidelines
      - Classify the issue: bug, feature, or enhancement.
      - Estimate the priority and the severity.
      - Identify the components that the issue affects.
      - Suggest labels and assignees.
      - If applicable, give the first troubleshooting steps.
```

### Security review

```yaml
- uses: cv/pi-action@v2
  with:
    github_token: ${{ secrets.GITHUB_TOKEN }}
    prompt_template: |
      # Security review: {{title}}

      ## Request
      {{task}}

      ## Details
      {{body}}

      ## Changes
      {{diff}}

      ## Checklist
      - Input validation and sanitization
      - Authentication and authorization
      - Encryption and storage of data
      - SQL injection
      - Cross-site scripting (XSS)
      - Cross-site request forgery (CSRF)
      - Vulnerable dependencies
      - Management of secrets
```

### Work that pi must commit

Because a template replaces the requirements block, add your own instruction when pi must change files:

```yaml
- uses: cv/pi-action@v2
  with:
    github_token: ${{ secrets.GITHUB_TOKEN }}
    prompt_template: |
      # {{type_display}} #{{number}}: {{title}}

      {{body}}

      ## Task
      {{task}}

      ## Requirements
      The runner is deleted after this run. Commit and push all changes before you finish.
```

## Troubleshooting

| Problem | Cause and solution |
|---------|--------------------|
| A variable is not replaced | The name is not correct. Names are case-sensitive: use `{{type_display}}`, not `{{Type_Display}}` |
| pi does not commit its work | A template does not include the requirements block. Add an instruction (see [the example](#work-that-pi-must-commit)) |
| A later comment does not use the template | This is correct. The template is only for the first message of a new thread. Later comments are [follow-ups](#prompts-and-templates) |
| The template has no effect | The template is empty or has only spaces, so pi-action uses the built-in prompt |
